import json
import sys

start = int(sys.argv[1])
end = int(sys.argv[2])
max_len = int(sys.argv[3]) if len(sys.argv) > 3 else 1500

with open("incidencias.jsonl") as f:
    for i, line in enumerate(f, 1):
        if start <= i <= end:
            d = json.loads(line)
            print(f"=== {i}: {d['id']} | {d['titulo']} ===")
            t = d["texto"]
            if len(t) > max_len:
                print(t[:max_len] + f"\n...[TRUNCATED {len(t)} chars]...")
            else:
                print(t)
            print()

import json, re, sys

start = int(sys.argv[1])
end = int(sys.argv[2])

with open("incidencias.jsonl") as f:
    for i, l in enumerate(f, 1):
        if not (start <= i <= end):
            continue
        d = json.loads(l)
        t = d["texto"]
        cleaned = re.sub(r"```json.*?```", "[JSON_OMITTED]", t, flags=re.S)
        if len(cleaned) > 950:
            print(f"=== {i}: {d['id']} | {d['titulo']} ===")
            print(cleaned[800:3000])
            if len(cleaned) > 3000:
                print(f"...[MORE {len(cleaned)} chars]...")
            print()

